"""Read-only inventory and identity checks for the new-experiment runtime bundle."""

import importlib.util
import json
import os
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
PHASE = 'result-coordinate-evidence/namespace-followup'
MANIFEST = PHASE + '/delivery/runtime-bundle-manifest.json'
sys.path.insert(0, str(ROOT / 'result-coordinate-evidence/materializer-followup'))
from comparison_runtime_io import (Inventory, file_hash, json_bytes, member_relative, path_under, portable,
                                   publish_no_replace, real_tree, recorded_relative, require, sha_bytes,
                                   signature, tree_digest)


def import_path(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def catalog(repo, inventory):
    identity = import_path('next_experiment_identity', repo / 'result-coordinate-evidence/materializer-followup/runtime_identity.py')
    original_cp, original_manifest = identity.original_identity()
    comparison = import_path('next_experiment_comparison', repo / PHASE / 'frame-directory-guard/run-comparison.py')
    protocol, primary = comparison.validate_protocol(repo / PHASE / 'frame-directory-guard/protocol.json')
    artifacts, runtimes = {}, {}

    def register(name, classpath, manifest, source_identity, descriptor=None):
        require(classpath == os.pathsep.join(item['path'] for item in manifest), 'Classpath order differs: ' + name)
        entries = []
        for item in manifest:
            relative = recorded_relative(item['path'], str(repo))
            if relative not in artifacts:
                if item['kind'] == 'tree':
                    files = inventory.tree(relative)
                    require(len(files) == item['files'] and tree_digest(files) == item['sha256'], 'Changed artifact: ' + relative)
                else:
                    require(item['kind'] == 'file' and relative.endswith('.jar'), 'Unexpected runtime artifact type')
                    inventory.add(relative, item['sha256'])
                artifacts[relative] = item | {'path': 'rdf4j/' + relative, 'originalAbsolutePath': item['path']}
            else:
                existing = artifacts[relative]
                require(existing['sha256'] == item['sha256'] and existing['kind'] == item['kind'], 'Conflicting artifact identity')
            entries.append(artifacts[relative]['path'])
        runtimes[name] = {'originalClasspath': classpath, 'originalManifest': manifest,
                          'entries': entries, 'sourceIdentity': source_identity, 'descriptor': descriptor}

    def descriptor_runtime(name, relative):
        descriptor = inventory.json(relative)
        inputs = comparison.descriptor_inputs(descriptor)
        for path in inputs.values():
            inventory.add(recorded_relative(str(path), str(repo)))
        cp = inventory.read(recorded_relative(descriptor['classpathFile'], str(repo))).decode().strip()
        manifest = inventory.json(recorded_relative(descriptor['classpathManifestFile'], str(repo)))
        register(name, cp, manifest, descriptor['sourceIdentity'], descriptor)
        runtimes[name]['descriptorPath'] = 'rdf4j/' + relative
        return manifest

    register('original-base', original_cp, original_manifest, identity.ORIGINAL_SOURCE)
    common = descriptor_runtime('primary-original', PHASE + '/compiled-v1/runtimes/original/runtime-descriptor.json')
    require(len(common) == 128 and common[1:] == original_manifest, 'Common harness changed base runtime')
    candidate_base = descriptor_runtime('candidate-base', PHASE + '/runtimes/frame-directory-guard/runtime-descriptor.json')
    require(len(candidate_base) == 127 and all(candidate_base[i] == original_manifest[i] for i in range(127) if i != 1),
            'Candidate changed an unexpected base entry')
    candidate = descriptor_runtime('primary-candidate', PHASE + '/frame-directory-guard/candidate-runtime/runtime-descriptor.json')
    require(candidate == [common[0]] + candidate_base, 'Candidate/common-harness composition differs')
    require(primary['original']['manifest'] == common and primary['candidate']['manifest'] == candidate,
            'Archived comparison protocol differs from runtime catalog')
    for name, relative in (
        ('namespace-diagnostic-v1', PHASE + '/compiled-v1/runtimes/diagnostic-original/runtime-descriptor.json'),
        ('namespace-diagnostic-v2', PHASE + '/compiled-diagnostic-v2/runtime-descriptor.json')):
        diag = descriptor_runtime(name, relative)
        require(len(diag) == 129 and diag[2:] == original_manifest, 'Diagnostic changed original base entries')
    shared_module = import_path('next_experiment_shared', repo / PHASE / 'shared-selection/run_shared_selection.py')
    shared_plan = shared_module.read_plan()
    shared_runtime = shared_module.read_runtime(shared_plan)
    register('shared-selection', shared_runtime['classpath'], shared_runtime['manifest'], shared_plan['frozenProductionSource'])
    require(shared_runtime['manifest'][1:] == original_manifest, 'Shared fixture changed base entries')
    page_module = import_path('next_experiment_page', repo / PHASE / 'shared-selection/page-occupancy/run_page_diagnostic.py')
    page_plan, _ = page_module.read_plan()
    page_runtime = page_module.read_runtime(page_plan)
    register('page-occupancy', page_runtime['classpath'], page_runtime['manifest'], page_plan['instrumentedIdentity'])
    require(page_runtime['manifest'][1:] == shared_runtime['manifest'], 'Page diagnostic changed shared/base entries')
    raw_relative = PHASE + '/shared-selection/page-occupancy/compiled-output'
    raw_files = inventory.tree(raw_relative)
    require(raw_files == page_runtime['rawCompiledFiles'], 'Raw page-diagnostic compiler output changed')
    require(len(artifacts) == 134 and len(runtimes) == 8, 'Unexpected unique-artifact/runtime count')
    command_files = []
    primary_root = repo / PHASE / 'frame-directory-guard/comparison-v1'
    primary_commands = sorted(primary_root.glob('round-*/command.json'))
    require(len(primary_commands) == 18, 'The primary experiment does not contain eighteen commands')
    command_files += [('primary', p.relative_to(repo).as_posix()) for p in primary_commands]
    command_files += [('diagnostic', PHASE + '/diagnostic-original-v1/command.json'),
                      ('diagnostic', PHASE + '/diagnostic-original-v2/command.json')]
    command_files += [('shared-pilot', PHASE + '/shared-selection/pilot/' + arm + '/command.json')
                      for arm in ('off', 'dense', 'rows')]
    command_files += [('page-diagnostic', PHASE + '/shared-selection/page-occupancy/run/command.json')]
    commands = []
    for index, (purpose, relative) in enumerate(command_files):
        record = inventory.json(relative)
        argv = record['argv']
        require(argv.count('-cp') == 1 and record['cwd'] == str(repo), 'Unexpected command classpath/cwd')
        classpath = argv[argv.index('-cp') + 1]
        matches = [name for name, runtime in runtimes.items() if runtime['originalClasspath'] == classpath]
        require(len(matches) == 1, 'Command does not identify one frozen runtime')
        runtime = matches[0]
        require('--source=' + runtimes[runtime]['sourceIdentity'] in argv, 'Command source identity differs')
        main = argv[argv.index('-cp') + 2]
        require(main in {'org.eclipse.rdf4j.sail.lmdb.evaluation.RootQualifiedOptionalFanoutLauncher',
                         'org.eclipse.rdf4j.sail.lmdb.evaluation.RootQualifiedSharedSelectionLauncher'}, 'Unexpected Java entry point')
        expected_samples = relative.removesuffix('command.json') + 'samples.jsonl'
        data = inventory.read(expected_samples)
        metadata = json.loads(data.splitlines()[0])
        require(metadata['source'] == runtimes[runtime]['sourceIdentity'], 'Recorded metadata source differs')
        commands.append({'label': f'{index:02d}-' + relative.split('/')[-2], 'purpose': purpose,
                         'runtime': runtime, 'recordPath': 'rdf4j/' + relative,
                         'originalArgv': argv, 'originalCwd': record['cwd'],
                         'originalSamplesPath': 'rdf4j/' + expected_samples,
                         'expectedMetadata': metadata, 'timeoutSeconds': 240 if purpose == 'primary' else 300})
    return {'artifacts': list(artifacts.values()), 'runtimes': runtimes, 'commands': commands,
            'primaryProtocolSha256': inventory.add(PHASE + '/frame-directory-guard/protocol.json')['sha256'],
            'rawCompilerOutput': {'path': 'rdf4j/' + raw_relative, 'files': raw_files}}


def validate_extracted(repo, expected_manifest=None):
    manifest_path = path_under(repo, MANIFEST)
    data = manifest_path.read_bytes()
    require(expected_manifest is None or sha_bytes(data) == expected_manifest, 'Bundle manifest checksum differs')
    manifest = json.loads(data)
    require(manifest['format'] == 1 and manifest['archivePrefix'] == 'rdf4j'
            and manifest['selfContainedRuntime'] and not manifest['jdkIncluded'], 'Unexpected bundle manifest')
    inventory = Inventory(repo)
    for record in manifest['files']:
        relative = member_relative(record['path'])
        actual = inventory.add(relative, record['sha256'])
        require(actual == record, 'Extracted file metadata differs: ' + relative)
    for artifact in manifest['runtimeArtifacts']:
        relative = member_relative(artifact['path'])
        if artifact['kind'] == 'tree':
            files = inventory.tree(relative)
            require(len(files) == artifact['files'] and tree_digest(files) == artifact['sha256'], 'Extracted artifact differs')
        else:
            inventory.add(relative, artifact['sha256'])
    for name, runtime in manifest['runtimes'].items():
        require(runtime['originalClasspath'] == os.pathsep.join(entry['path'] for entry in runtime['originalManifest']),
                'Recorded classpath order differs: ' + name)
        require(len(runtime['entries']) == len(runtime['originalManifest']), 'Runtime entry count differs')
        artifacts = {entry['path']: entry for entry in manifest['runtimeArtifacts']}
        for path, original in zip(runtime['entries'], runtime['originalManifest']):
            require(path in artifacts, 'Runtime references an absent artifact')
            artifact = artifacts[path]
            require(artifact['originalAbsolutePath'] == original['path']
                    and artifact['kind'] == original['kind'] and artifact['sha256'] == original['sha256']
                    and artifact.get('files') == original.get('files'), 'Runtime artifact mapping differs')
    for command in manifest['commands']:
        raw = inventory.json(member_relative(command['recordPath']))
        require(raw['argv'] == command['originalArgv'] and raw['cwd'] == command['originalCwd'],
                'Recorded command differs from bundled original')
        runtime = manifest['runtimes'][command['runtime']]
        argv = command['originalArgv']
        require(argv.count('-cp') == 1 and argv[argv.index('-cp') + 1] == runtime['originalClasspath']
                and '--source=' + runtime['sourceIdentity'] in argv, 'Command/runtime binding differs')
    inventory.assert_stable()
    return manifest, sha_bytes(data)
